/* Fonte: prisma/schema.prisma */

export const PRISMA_SCHEMA = "// Schema dati target del portale B2B Valkiria Fluidodinamica S.r.l. (azienda fittizia).\n// Documentazione architetturale: nella sandbox pubblica i dati vivono in memoria,\n// in produzione questo schema è applicato a PostgreSQL 16 tramite Prisma Migrate.\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\nenum Role {\n  BUYER\n  TIER1\n  AGENT\n  ADMIN\n}\n\nenum ContractTier {\n  OFFERTA_BASE\n  CONTRATTO_QUADRO\n}\n\nenum OrderStatus {\n  DRAFT\n  SUBMITTED\n  PAID\n  INVOICED\n  CANCELLED\n}\n\nenum VatRegime {\n  ORDINARIA\n  ESENTE_ART8\n}\n\nenum WebhookOutcome {\n  PROCESSED\n  DUPLICATE_IGNORED\n  SIGNATURE_INVALID\n}\n\nmodel Company {\n  id                         String        @id @default(cuid())\n  legalName                  String\n  vatNumber                  String        @unique @db.VarChar(13)\n  sdiRecipientCode           String        @db.Char(7)\n  pec                        String\n  priceListTierId            String\n  priceListTier              PriceListTier @relation(fields: [priceListTierId], references: [id])\n  freeShippingThresholdCents Int\n  intentDeclarationProtocol  String?       @db.VarChar(32)\n  stripeCustomerId           String?       @unique\n  users                      User[]\n  orders                     B2BOrder[]\n  createdAt                  DateTime      @default(now())\n  updatedAt                  DateTime      @updatedAt\n\n  @@index([priceListTierId])\n}\n\nmodel User {\n  id        String   @id @default(cuid())\n  email     String   @unique\n  fullName  String\n  role      Role\n  companyId String?\n  company   Company? @relation(fields: [companyId], references: [id])\n  orders    B2BOrder[]\n  createdAt DateTime @default(now())\n\n  @@index([companyId, role])\n}\n\nmodel PriceListTier {\n  id                 String       @id @default(cuid())\n  tier               ContractTier @unique\n  contractCode       String       @unique\n  contractDiscountBp Int\n  /// Scaglioni volume serializzati: [{ minQty, maxQty, discountBp }]\n  volumeTiers        Json\n  validFrom          DateTime\n  validTo            DateTime?\n  companies          Company[]\n}\n\nmodel Product {\n  sku                 String      @id @db.VarChar(32)\n  name                String\n  category            String\n  maxPressureBar      Int\n  flowLpm             Int?\n  tempMinC            Int\n  tempMaxC            Int\n  weightGrams         Int\n  listPriceCents      Int\n  industrialCostCents Int\n  leadTimeDays        Int\n  stockBergamo        Int         @default(0)\n  stockBrescia        Int         @default(0)\n  /// Optimistic locking: ogni decremento giacenza incrementa la versione.\n  version             Int         @default(0)\n  orderLines          OrderLine[]\n  updatedAt           DateTime    @updatedAt\n\n  @@index([category])\n}\n\nmodel B2BOrder {\n  id              String      @id @default(cuid())\n  orderCode       String      @unique\n  /// Chiave di idempotenza inviata dal client: impedisce doppie emissioni.\n  idempotencyKey  String      @unique\n  companyId       String\n  company         Company     @relation(fields: [companyId], references: [id])\n  createdById     String\n  createdBy       User        @relation(fields: [createdById], references: [id])\n  status          OrderStatus @default(SUBMITTED)\n  vatRegime       VatRegime\n  paymentMethod   String\n  taxableCents    Int\n  shippingCents   Int\n  vatCents        Int\n  stampDutyCents  Int         @default(0)\n  totalCents      Int\n  stripeSessionId String?     @unique\n  invoiceNumber   String?     @unique\n  sdiIdentifier   String?\n  lines           OrderLine[]\n  webhookLogs     WebhookLog[]\n  createdAt       DateTime    @default(now())\n\n  @@index([companyId, createdAt(sort: Desc)])\n  @@index([status])\n}\n\nmodel OrderLine {\n  id                 String   @id @default(cuid())\n  orderId            String\n  order              B2BOrder @relation(fields: [orderId], references: [id], onDelete: Cascade)\n  sku                String\n  product            Product  @relation(fields: [sku], references: [sku])\n  quantity           Int\n  listUnitCents      Int\n  netUnitCents       Int\n  volumeTierLabel    String\n  overrideDiscountBp Int      @default(0)\n  lineNetCents       Int\n  fromBergamo        Int\n  fromBrescia        Int\n  backorder          Int\n\n  @@unique([orderId, sku])\n  @@index([sku])\n}\n\n/// Ogni consegna (anche duplicata o con firma non valida) viene registrata.\nmodel WebhookLog {\n  id                String         @id @default(cuid())\n  stripeEventId     String\n  type              String\n  orderId           String?\n  order             B2BOrder?      @relation(fields: [orderId], references: [id])\n  signatureVerified Boolean\n  outcome           WebhookOutcome\n  payload           Json\n  receivedAt        DateTime       @default(now())\n\n  @@index([stripeEventId])\n  @@index([orderId])\n  @@index([type, receivedAt(sort: Desc)])\n}\n\n/// Deduplica: un evento Stripe produce effetti di dominio al più una volta.\n/// L'INSERT avviene nella stessa transazione dell'effetto; la violazione della\n/// chiave primaria segnala un duplicato → risposta 200 con outcome DUPLICATE_IGNORED.\nmodel ProcessedStripeEvent {\n  eventId     String   @id\n  type        String\n  processedAt DateTime @default(now())\n}\n";
